import { LoginService } from './../services/login.service';
import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { NgForm, FormControl, Validators } from '@angular/forms';
import { Login } from '../../shared/models';
import { ActivatedRoute, Router } from '@angular/router';
import { ParticlesConfig } from './particles-config';

declare let particlesJS: any;

@Component({
    selector: 'app-login',
    templateUrl: './login.component.html',
    styleUrls: ['./login.component.scss']
})

export class LoginComponent implements OnInit {
    @ViewChild('formLogin') formLogin!: NgForm;
    @ViewChild('submitButton') submitButton!: ElementRef;
    login: Login = new Login();
    loading: boolean = false;
    loginError: string | null = null;
    message!: string;
    isCapsLock: boolean = false;

    constructor(
        private loginService: LoginService,
        private router: Router,
        private route: ActivatedRoute) {
        if (this.loginService.usuarioLogado) {
            this.router.navigate(["/homepage"]);
        }
    }

    ngOnInit(): void {
        this.route.queryParams.subscribe(params => {
            this.message = params['error'];
        });
        
        // Move the particlesJS initialization here
        setTimeout(() => {
            this.invokeParticles();
        });
    }

    public invokeParticles(): void {
        particlesJS('particles-js', ParticlesConfig, function() {});
    }

    logar(): void {
  this.loading = true;
  if (this.formLogin.form.valid) {
    if (this.login.login && /^[0-9]+$/.test(this.login.login)) {
      // Verifique se o login não contém caracteres especiais
      this.loginService.login(this.login).subscribe(
        (usu) => {
          if (usu != null) {
            this.loginService.usuarioLogado = usu;
            this.loading = false;
            this.router.navigate(['/servers']);
          } else {
            this.message = 'Usuário/Senha inválidos.';
          }
        },
        (error) => {
          // Exibe mensagens específicas com base nas respostas do console
          if (error.status === 401) {
            this.message = 'Usuário ou senha inválidos.';
          } else if (error.status === 403) {
            this.message = 'Você não tem permissão para acessar. Solicite um login válido.';
          } else {
            this.message = 'Erro desconhecido. Por favor, tente novamente mais tarde.';
          }
          this.loading = false;
        }
      );
    } else {
      this.message = 'O campo Login deve conter apenas números!';
    }
  }
  this.loading = false;
}

  checkCapsLock(event: KeyboardEvent) {
    if (event.getModifierState && event.getModifierState('CapsLock')) {
        this.isCapsLock = true;
    } else {
        this.isCapsLock = false;
    }
  }

}
