import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { ServerService } from './services/server.service';
import { ServerProtocol } from './models/server';

@Injectable({
  providedIn: 'root',
})
export class UserService {
  constructor(private http: HttpClient, private serverService: ServerService) {}

  private getApiUrl(endpoint: string): string {
    const localServer = this.serverService.getLocalServerDetails();
    if (localServer) {
      return `${localServer.protocol}//${localServer.host}:${localServer.port}/v2${endpoint}`;
    } else {
      // Caso o servidor local não esteja disponível, retorne uma mensagem de erro.
      throw new Error('Servidor local não disponível. Verifique a configuração.');
    }
  }

  getUsers(): Observable<any[]> {
    const apiUrl = this.getApiUrl('/usuarios');
    return this.http.get<any[]>(apiUrl);
  }

  addUser(user: any): Observable<any> {
    const apiUrl = this.getApiUrl('/usuarios');
    return this.http.post<any>(apiUrl, user);
  }

  deleteUser(userId: number): Observable<any> {
    const apiUrl = this.getApiUrl(`/usuarios/${userId}`);
    return this.http.delete<any>(apiUrl).pipe(
      map(response => response)
    );
  }

  getProjects(): Observable<any[]> {
    const apiUrl = this.getApiUrl('/projetos');
    return this.http.get<any[]>(apiUrl);
  }


updateUserProjects(userId: number, projects: string): Observable<any> {
  const apiUrl = this.getApiUrl(`/usuarios/${userId}/projetos`);
  
  // Converta a string JSON diretamente para um array de objetos, sem manipulação adicional
  const projectsArray = JSON.parse(projects);

  return this.http.put<any>(apiUrl, { projetos: projectsArray }).pipe(
    map(response => response)
  );
}


  getUser(userId: number): Observable<any> {
    const apiUrl = this.getApiUrl(`/usuarios/${userId}`);
    return this.http.get<any>(apiUrl);
  }

  updateUser(userId: number, userData: any): Observable<any> {
    const updatedUserDataWithPassword = {
      ...userData,
      senha: userData.senha || null,
    };

    const updatedUserDataWithProjects = {
      ...updatedUserDataWithPassword,
      projetos: JSON.parse(updatedUserDataWithPassword.projetos),
    };

    const apiUrl = this.getApiUrl(`/usuarios/${userId}`);
    return this.http.put<any>(apiUrl, updatedUserDataWithProjects).pipe(
      map(response => response)
    );
  }
}
