import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Project } from '../models/project';
import { Server } from '../models/server';
import { RecentlyOpenedProjectService } from '../services/recentlyOpenedProject.service';

@Component({
    selector: 'app-retractable-modal',
    templateUrl: './retractable-modal.component.html',
    styleUrls: ['./retractable-modal.component.scss']
})
export class RetractableModalComponent implements OnInit {

    @ViewChild('customContent', { static: true }) customContent: ElementRef;
    isMenuVisible: boolean = false;
    public projectId: string;
    public server: Server;
    public nameProject: string;
    public project: Project;
    htmlContent: string = '';
    recentlyOpenedProjectId: string;


    constructor(
        private http: HttpClient,
        private recentlyOpenedProjectService: RecentlyOpenedProjectService,
    ) {}

   
    ngOnInit(): void {
            this.recentlyOpenedProjectId = this.recentlyOpenedProjectService.getProjectId();
            this.projectId = this.recentlyOpenedProjectId;
            this.loadHtmlContent(); // Carrega o conteúdo HTML do arquivo correspondente
    }

    toggleMenu() {
        this.isMenuVisible = !this.isMenuVisible;
    }

    loadHtmlContent() {
        // Carrega o conteúdo HTML dinamicamente com base no projectId
        this.http.get(`assets/resources/tutorial/html/${this.projectId}.html`, { responseType: 'text' })
            .subscribe(
                (data: string) => {
                    this.htmlContent = data;
                },
                (error) => {
                    console.error('Erro ao carregar conteúdo HTML:', error);
                }
            );
    }
}
