import { Component, OnInit } from '@angular/core';
import { Usuario } from '../../app/shared/models/usuario.model';
import { LoginService } from '../auth/services/login.service';
import { UserService } from '../user.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-usuarios',
  templateUrl: './usuarios.component.html',
  styleUrls: ['./usuarios.component.scss'],
})
export class UsuariosComponent implements OnInit {
  usuarios: any[] = [];
  usuarioLogado: Usuario;
  successMessage: string = '';
  errorMessage: string = '';

  filtroCurso: string = '';
  filtroPerfil: string = '';
  filtroLogin: string = '';

  constructor(
    private userService: UserService,
    private loginService: LoginService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.usuarioLogado = this.loginService.usuarioLogado;
    this.loadUsuarios();
  }

  loadUsuarios(): void {
    this.userService.getUsers().subscribe((usuarios) => {
      this.usuarios = usuarios;
    });
  }

  usuariosFiltrados(): any[] {
    return this.usuarios.filter((usuario) => {
      return (
        (!this.filtroCurso || usuario.curso === this.filtroCurso) &&
        (!this.filtroPerfil || usuario.perfil === this.filtroPerfil) &&
        (!this.filtroLogin || usuario.login.includes(this.filtroLogin))
      );
    });
  }

  viewUser(userId: number): void {
    this.router.navigate(['/user-view', userId]);
  }

  deleteUser(userId: number): void {
    const confirmDelete = confirm('Deseja realmente excluir este usuário?');
    if (confirmDelete) {
      this.userService.deleteUser(userId).subscribe(
        () => {
          this.loadUsuarios();
          this.successMessage = 'Usuário excluído com sucesso!';
          setTimeout(() => {
            this.successMessage = '';
          }, 5000);
        },
        (error) => {
          this.errorMessage = 'Erro ao excluir usuário. Verifique a console para detalhes.';
          setTimeout(() => {
            this.errorMessage = '';
          }, 5000);
        }
      );
    }
  }
}
