import { Component, OnInit } from '@angular/core';

@Component({
  selector: 'app-contador',
  templateUrl: './contador.component.html',
  styleUrls: ['./contador.component.scss']
})


export class ContadorComponent {
 countdownDate: string;
  timerInterval: any;

  constructor() { }

  startCountdown(): void {
    clearInterval(this.timerInterval);
    const deadline = new Date(this.countdownDate).getTime();
    this.timerInterval = setInterval(() => {
      const now = new Date().getTime();
      const t = deadline - now;
      const hours = Math.floor((t % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
      const minutes = Math.floor((t % (1000 * 60 * 60)) / (1000 * 60));
      const seconds = Math.floor((t % (1000 * 60)) / 1000);

      const hourElem = document.getElementById('hour');
      if (hourElem) {
        hourElem.innerHTML = hours.toString().padStart(2, '0');
      }

      const minuteElem = document.getElementById('minute');
      if (minuteElem) {
        minuteElem.innerHTML = minutes.toString().padStart(2, '0');
      }

      const secondElem = document.getElementById('second');
      if (secondElem) {
        secondElem.innerHTML = seconds.toString().padStart(2, '0');
      }

      if (t < 600000) { // se faltar 10 minutos
        if (hourElem) {
          hourElem.style.color = 'red';
        }
        if (minuteElem) {
          minuteElem.style.color = 'red';
        }
        if (secondElem) {
          secondElem.style.color = 'red';
        }
      }

      if (t < 0) {
        clearInterval(this.timerInterval);
        document.getElementById('demo').innerHTML = 'TEMPO ENCERRADO!';
        if (hourElem) {
          hourElem.innerHTML = '00';
        }
        if (minuteElem) {
          minuteElem.innerHTML = '00';
        }
        if (secondElem) {
          secondElem.innerHTML = '00';
        }
      }
    }, 1000);
  }
}
