import { Injectable } from '@angular/core';
import { Observable, throwError } from 'rxjs';
import { Usuario } from '../../../app/shared/models/usuario.model';
import { Login } from '../../../app/shared/models/login.model';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { catchError, map } from 'rxjs/operators';
import * as CryptoJS from 'crypto-js';
import { ServerService } from '../../services/server.service';
import { ServerProtocol } from '../../models/server';

const SS_CHAVE: string = "usuarioLogado";

@Injectable({
  providedIn: 'root',
})
export class LoginService {

  constructor(private http: HttpClient, private serverService: ServerService) {}

  private getApiUrl(endpoint: string): string {
    const localServer = this.serverService.getLocalServerDetails();
    if (localServer) {
      return `${localServer.protocol}//${localServer.host}:${localServer.port}/v2${endpoint}`;
    } else {
      // Caso o servidor local não esteja disponível, retorne uma mensagem de erro.
      throw new Error('Servidor local não disponível. Verifique a configuração.');
    }
  }

  public get usuarioLogado(): Usuario {
    let usu = sessionStorage.getItem(SS_CHAVE);
    return usu ? JSON.parse(usu) : null;
  }

  public set usuarioLogado(usuario: Usuario) {
    if (usuario) {
      sessionStorage.setItem(SS_CHAVE, JSON.stringify(usuario));
    } else {
      sessionStorage.removeItem(SS_CHAVE);
    }
  }

  logout() {
    sessionStorage.removeItem(SS_CHAVE);
    sessionStorage.removeItem("session");
  }

  private extractProjectsData(projects: string): { id: string; name: string }[] {
    try {
      const projetos = JSON.parse(projects);
      if (Array.isArray(projetos)) {
        return projetos.map(project => ({ id: project.project_id, name: project.name }));
      } else {
        return [];
      }
    } catch (error) {
      console.error('Erro ao fazer parse dos projetos:', error);
      return [];
    }
  }

  login(login: Login): Observable<Usuario | null> {
    const url = this.getApiUrl('/login');

    // Converta a senha para MD5 usando crypto-js
    const loginComMD5 = {
      login: login.login,
      senha: CryptoJS.MD5(login.senha).toString(),
    };

    return this.http.post<any>(url, loginComMD5).pipe(
      map((data: any) => {
        if (data && data.projetos) {
          // Converta os dados de projetos conforme necessário
          const projetos = this.extractProjectsData(data.projetos);
          // Armazene o usuário logado na sessão
          const usu: Usuario = {
            id: data.id,
            login: data.login,
            nome: data.nome,
            curso: data.curso,
            senha: data.senha,
            perfil: data.perfil,
            projetos: projetos,
            ultimo_login: data.ultimo_login,
          };
          this.usuarioLogado = usu;
          return usu;
        } else {
          return null;
        }
      }),
      catchError((error: HttpErrorResponse) => {
        console.error('Erro na requisição de login:', error);
        return throwError(error);
      })
    );
  }
}
