import { Component, OnInit, AfterViewInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { UserService } from '../user.service';
import { Usuario } from "../../app/shared/models/usuario.model";
import { LoginService } from "../auth/services/login.service";
import { D3Service, D3 } from 'd3-ng2-service';
import { scaleBand, scaleLinear, axisBottom, axisLeft } from 'd3';

@Component({
  selector: 'app-user-view',
  templateUrl: './user-view.component.html',
  styleUrls: ['./user-view.component.scss'],
})
export class UserViewComponent implements OnInit, AfterViewInit {
  userId: number;
  user: any;
  chartTitle: string;
  projects: any[];
  usuarioLogado: Usuario;
  private d3: D3;
  private svg: any;
  private margin = { top: 40, right: 20, bottom: 20, left: 60 };
  private width = 900 - this.margin.left - this.margin.right;
  private height = 370 - this.margin.top - this.margin.bottom;

  // Variáveis para controle de filtro
  accessOptions = [5, 10, 50, 100];
  selectedAccessCount = 5;
  filteredAccesses = [];

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private userService: UserService,
    private loginService: LoginService,
    private d3Service: D3Service
  ) {
    this.d3 = d3Service.getD3();
  }

  ngOnInit(): void {
    this.setChartTitle();
    this.usuarioLogado = this.loginService.usuarioLogado;
    this.route.params.subscribe((params) => {
      this.userId = +params['id'];
      this.loadUserData();
    });
  }

  ngAfterViewInit(): void {
    if (this.user) {
      this.createChart();
    }
  }

  loadUserData(): void {
    this.userService.getUsers().subscribe((users) => {
      this.user = users.find((u) => u.id === this.userId);

      if (this.user) {
        this.userService.getProjects().subscribe((projects) => {
          this.projects = projects.filter((project) => this.user.projetos.includes(project.project_id));
        });
        setTimeout(() => {
          this.createChart();
          this.filterAccesses(); // Filtra acessos quando os dados são carregados
        }, 0);  // Ensure data is loaded before chart creation
      } else {
        this.router.navigate(['/usuarios']);
      }
    });
  }

  createChart(): void {
    const data = this.formatData(this.user.acessos);

    if (data.length === 0) {
      console.error('Nenhum dado para exibir no gráfico.');
      return;
    }

    this.svg = this.d3.select('.chart')
      .attr('width', this.width + this.margin.left + this.margin.right)
      .attr('height', this.height + this.margin.top + this.margin.bottom)
      .append('g')
      .attr('transform', `translate(${this.margin.left},${this.margin.top})`);

    const x = scaleBand()
      .domain(data.map(d => d.week))
      .range([0, this.width])
      .padding(0.1);

    const y = scaleLinear()
      .domain([0, 1]) // The height is a proportion from 0 to 1
      .nice()
      .range([this.height, 0]);

    // Adiciona barras
    this.svg.selectAll('.bar')
      .data(data)
      .enter().append('rect')
      .attr('class', 'bar')
      .attr('x', d => x(d.week))
      .attr('y', d => y(d.proportion))
      .attr('width', x.bandwidth())
      .attr('height', d => this.height - y(d.proportion))
      .style('fill', '#00e5ff');

    // Adiciona eixos
    this.svg.append('g')
      .attr('class', 'x-axis')
      .attr('transform', `translate(0,${this.height})`)
      .call(axisBottom(x).tickFormat((d, i) => `Semana ${i + 1}`));

    this.svg.append('g')
      .attr('class', 'y-axis')
      .call(axisLeft(y).ticks(5).tickFormat(d => `${Math.round(d * 7)} dias`));
  }

  formatData(acessos): any[] {
    const now = new Date();
    const currentMonth = now.getMonth(); // Mês atual
    const weeksInMonth = Array.from({ length: 4 }, (_, i) => ({
      week: `Semana ${i + 1}`,
      accessDays: new Set()
    }));

    acessos.forEach(acesso => {
      const date = new Date(acesso); // Use a data ISO diretamente
      const weekIndex = Math.floor(date.getDate() / 7); // Identifique a semana do mês para cada acesso

      if (date.getMonth() === currentMonth && weekIndex < weeksInMonth.length) {
        weeksInMonth[weekIndex].accessDays.add(date.getDay()); // Adicione o dia da semana ao conjunto
      }
    });

    const data = weeksInMonth.map(week => ({
      week: week.week,
      proportion: week.accessDays.size / 7 // Proporção de dias de acesso em relação a 7 dias
    }));

    return data;
  }

  setChartTitle(): void {
    const now = new Date();
    const monthNames = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];
    const year = now.getFullYear();
    const month = monthNames[now.getMonth()];
    this.chartTitle = `Acesso mensal - ${month} / ${year}`;
  }

  filterAccesses(): void {
    if (this.user && this.user.acessos) {
      this.filteredAccesses = this.user.acessos.slice(0, this.selectedAccessCount);
    }
  }


  goBackToList(): void {
    this.router.navigate(['/usuarios']);
  }
}
