import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { Usuario } from "../../app/shared/models/usuario.model";
import { LoginService } from "../auth/services/login.service";
import * as jsPDF from 'jspdf';

@Component({
  selector: 'app-pdf-form',
  templateUrl: './pdf-form.component.html',
  styleUrls: ['./pdf-form.component.scss']
})
export class PdfFormComponent implements OnInit {
  @ViewChild('modal') modal: ElementRef;
  usuarioLogado: Usuario;
  isDragging = false;
  initialX = 0;
  initialY = 0;
  questao: string = '';
  item: string = '';
  texto: string = '';
  nomeDocumento: string = '';
  nrIdentificacao: string = '';
  showModal = false; // Variável para controlar o estado do modal

  constructor(private loginService: LoginService) { }

  ngOnInit(): void {
     // Obtenha o usuário logado do serviço de login
     this.usuarioLogado = this.loginService.usuarioLogado;
  }

  openModal(): void {
    this.showModal = true; // Altera o estado para true ao clicar no botão
  }

  closeModal(): void {
    this.showModal = false; // Altera o estado para false ao fechar o modal
  }

  onMouseDown(event: MouseEvent): void {
    this.isDragging = true;
    this.initialX = event.clientX - this.modal.nativeElement.offsetLeft;
    this.initialY = event.clientY - this.modal.nativeElement.offsetTop;
  }

  onMouseMove(event: MouseEvent): void {
    if (this.isDragging) {
      const newX = event.clientX - this.initialX;
      const newY = event.clientY - this.initialY;
      this.modal.nativeElement.style.left = `${newX}px`;
      this.modal.nativeElement.style.top = `${newY}px`;
    }
  }

  onMouseUp(): void {
    this.isDragging = false;
  }
  
  salvarPdf(): void {
    // Verifica se todos os campos requeridos estão preenchidos
    if (!this.questao || !this.item || !this.texto || !this.nomeDocumento || !this.nrIdentificacao) {
      // Se algum campo estiver vazio, exibe um alerta
      alert('Preencha todos os campos obrigatórios.');
      return; // Sai da função, não continua com a geração do PDF
    }
  
    const doc = new jsPDF.default();
  
    // Determina o título do PDF de acordo com o curso
    let tituloCurso = '';
    if (this.usuarioLogado.curso === 'OPTIC') {
      tituloCurso = 'Curso de Operador de Tecnologia da Informação e Comunicação';
    } else if (this.usuarioLogado.curso === 'PROTCIBER') {
      tituloCurso = 'Curso de Proteção Cibernética';
    } else if (this.usuarioLogado.curso === 'EGPC') {
      tituloCurso = 'Estágio Geral de Proteção Cibernética';
    }  else if (this.usuarioLogado.curso === 'PCI') {
      tituloCurso = 'Pedido de Cooperação de Instrução';
    } else {
      tituloCurso = 'Instrutor';
    }
  
    const titulo = `${tituloCurso} - Avaliação de Controle`;
  
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
  
    // Calcula o tamanho do título usando a função getTextWidth()
    const tituloWidth = doc.getTextWidth(titulo);
  
    const x = (doc.internal.pageSize.width - tituloWidth) / 2;
    doc.text(titulo, x, 20);
  
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
  
    // Adiciona os itens com quebras de linha
    doc.setFont('helvetica', 'bold');
    doc.text('Nr de Identificação da Prova:', 10, 40);
    doc.setFont('helvetica', 'normal');
    doc.text(this.nrIdentificacao, 80, 40);
  
    doc.setFont('helvetica', 'bold');
    doc.text('Questão:', 10, 50);
    doc.setFont('helvetica', 'normal');
    doc.text(this.questao, 40, 50);
  
    doc.setFont('helvetica', 'bold');
    doc.text('Item:', 10, 60);
    doc.setFont('helvetica', 'normal');
    doc.text(this.item, 30, 60);
  
    doc.setFont('helvetica', 'bold');
    doc.text('Solução:', 10, 70);
    doc.setFont('courier', 'normal');
    
    const splitTextOptions = {
      maxWidth: doc.internal.pageSize.width - 20
    };
    const textLines = doc.splitTextToSize(this.texto, splitTextOptions.maxWidth);
  
    let currentPage = 1;
    let yPosition = 80;
  
    textLines.forEach((line, index) => {
      if (yPosition + 10 > doc.internal.pageSize.height) {
        doc.addPage();
        currentPage++;
        yPosition = 10;
      }
      doc.text(line, 10, yPosition);
      yPosition += 10;
    });
  
    // Adiciona o rodapé com a data e hora de criação do documento
    const dataHora = new Date().toLocaleString();
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.text(`SPIDER Web UI - Gerado em: ${dataHora}. Páginas: ${currentPage}`, 14, doc.internal.pageSize.height - 10);
  
    if (this.nomeDocumento) {
      doc.save(`${this.nrIdentificacao}_${this.nomeDocumento}.pdf`);
    } else {
      doc.save(`documento.pdf`);
    }
  
    this.questao = '';
    this.item = '';
    this.texto = '';
    this.nomeDocumento = '';
    this.nrIdentificacao = '';
  
    this.closeModal();
  }
}
