import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { UserService } from '../user.service';
import { Usuario } from "../../app/shared/models/usuario.model";
import { LoginService } from "../auth/services/login.service";
import * as CryptoJS from 'crypto-js';

@Component({
  selector: 'app-add-user',
  templateUrl: './add-user.component.html',
  styleUrls: ['./add-user.component.scss'],
})
export class AddUserComponent implements OnInit {
  userForm: FormGroup;
  projects: any[] = [];
  selectedProjects: any[] = [];
  message: string = '';
  isSuccess: boolean;
  addedUser: any;
  usuarioLogado: Usuario;
  showPassword: boolean = false;

  constructor(
    private fb: FormBuilder,
    private userService: UserService,
    private loginService: LoginService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.initForm();
    this.loadProjects();
    this.usuarioLogado = this.loginService.usuarioLogado;
  }

  initForm(): void {
    this.userForm = this.fb.group(
      {
        login: ['', Validators.required],
        senha: ['', Validators.required],
        confirmarSenha: ['', Validators.required],
        perfil: ['', Validators.required],
        nome: ['', Validators.required],
        curso: ['', Validators.required],
        projetos: this.fb.array([]),
      },
      { validator: this.passwordMatchValidator }
    );
  }

  passwordMatchValidator(g: FormGroup) {
    return g.get('senha').value === g.get('confirmarSenha').value
      ? null
      : { mismatch: true };
  }

  checkPasswords() {
    const senha = this.userForm.get('senha').value;
    const confirmarSenha = this.userForm.get('confirmarSenha').value;
    if (senha !== confirmarSenha) {
      this.userForm.get('confirmarSenha').setErrors({ mismatch: true });
    } else {
      this.userForm.get('confirmarSenha').setErrors(null);
    }
  }

  togglePasswordVisibility(): void {
    this.showPassword = !this.showPassword;
  }

  loadProjects(): void {
    this.userService.getProjects().subscribe((projects) => {
      this.projects = projects.map((project) => ({ ...project, checked: false }));
    });
  }

  toggleProject(project: any): void {
    project.checked = !project.checked;
    this.selectedProjects = this.projects.filter((p) => p.checked);
  }

  addUser(): void {
    if (this.userForm.invalid) {
      this.message = 'Por favor, preencha todos os campos obrigatórios.';
      this.isSuccess = false;
      this.clearMessageAfterDelay();
      return;
    }

    const user = this.userForm.value;

    // Mapear os projetos para o formato correto
    user.projetos = this.selectedProjects.map((project) => ({
      id: project.project_id,
      name: project.name,
      project_id: project.project_id,
    }));

    // Converta a lista de projetos para uma string JSON válida
    user.projetos = JSON.stringify(user.projetos);

    // Converta a senha para MD5
    user.senha = CryptoJS.MD5(user.senha).toString();

    this.userService.addUser(user).subscribe(
      (addedUser) => {
        this.message = 'Usuário adicionado com sucesso!';
        this.isSuccess = true;
        this.addedUser = addedUser;
        this.userForm.reset();
        this.selectedProjects = [];
        this.clearMessageAfterDelay();
      },
      (error) => {
        console.error('Erro ao adicionar usuário:', error);
        this.message =
          'Erro ao adicionar usuário. Verifique os campos e tente novamente.';
        this.isSuccess = false;
        this.clearMessageAfterDelay();
      }
    );
  }

  private clearMessageAfterDelay(): void {
    // Limpar a mensagem após 3 segundos (3000 milissegundos)
    setTimeout(() => {
      this.message = '';
      this.isSuccess = undefined; // Limpar também o status de sucesso
    }, 5000);
  }

  goBackToList(): void {
    this.router.navigate(['/usuarios']);
  }
}
