import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { UserService } from '../user.service';
import { Usuario } from "../../app/shared/models/usuario.model";
import { LoginService } from "../auth/services/login.service";
import * as CryptoJS from 'crypto-js';

@Component({
  selector: 'app-edit-user',
  templateUrl: './edit-user.component.html',
  styleUrls: ['./edit-user.component.scss'],
})
export class EditUserComponent implements OnInit {
  userForm: FormGroup;
  projects: any[] = [];
  selectedProjects: any[] = [];
  message: string = '';
  isSuccess: boolean;
  editedUser: any;
  userId: number;
  usuarioLogado: Usuario;
  showPassword: boolean = false;

  constructor(
    private fb: FormBuilder,
    private userService: UserService,
    private loginService: LoginService,
    private route: ActivatedRoute,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.initForm();
    this.loadProjects();
    this.usuarioLogado = this.loginService.usuarioLogado;

    this.route.params.subscribe((params) => {
      this.userId = +params['id'];
      this.loadUserData(this.userId);
    });
  }

  initForm(): void {
    this.userForm = this.fb.group(
      {
        login: ['', Validators.required],
        senha: [''],
        confirmarSenha: [''],
        perfil: ['', Validators.required],
        nome: ['', Validators.required],
        curso: ['', Validators.required],
        projetos: this.fb.array([]),
      },
      { validator: this.passwordMatchValidator }
    );
  }

  passwordMatchValidator(g: FormGroup) {
    return g.get('senha').value === g.get('confirmarSenha').value
      ? null
      : { mismatch: true };
  }

  checkPasswords() {
    const senha = this.userForm.get('senha').value;
    const confirmarSenha = this.userForm.get('confirmarSenha').value;
    if (senha !== confirmarSenha) {
      this.userForm.get('confirmarSenha').setErrors({ mismatch: true });
    } else {
      this.userForm.get('confirmarSenha').setErrors(null);
    }
  }

  togglePasswordVisibility(): void {
    this.showPassword = !this.showPassword;
  }

loadUserData(userId: number): void {
  this.userService.getUser(userId).subscribe(
    (user) => {
      this.userForm.patchValue({
        login: user.login,
        senha: '', // Deixe a senha em branco para a edição
        confirmarSenha: '', // Limpe o campo de confirmação de senha
        perfil: user.perfil,
        nome: user.nome,
        curso: user.curso,
      });

      // Certifique-se de que this.projects é inicializado como uma array vazia, se necessário
      this.projects = this.projects || [];

      // Carregue os projetos do usuário
      const userProjects = JSON.parse(user.projetos || '[]');
      this.projects = this.projects.map((project) => ({
        ...project,
        checked: userProjects.some((userProject) => userProject.project_id === project.project_id),
      }));
      this.selectedProjects = this.projects.filter((p) => p.checked);
    },
    (error) => {
      console.error('Erro ao carregar usuário:', error);
      // Se ocorrer um erro ao carregar o usuário, você pode redirecionar para a lista de usuários ou tomar outra ação adequada.
    }
  );
}

  loadProjects(): void {
    this.userService.getProjects().subscribe((projects) => {
      this.projects = projects.map((project) => ({ ...project, checked: false }));
    });
  }

  toggleProject(project: any): void {
    project.checked = !project.checked;
    this.selectedProjects = this.projects.filter((p) => p.checked);
  }

updateUser(): void {
  if (this.userForm.invalid) {
    this.message = 'Por favor, preencha todos os campos obrigatórios.';
    this.isSuccess = false;
    this.clearMessageAfterDelay();
    return;
  }

  const user = { ...this.userForm.value }; // Use o spread operator para evitar alterar diretamente o valor do formulário

  // Converta a senha para MD5
  if (user.senha) {
    user.senha = CryptoJS.MD5(user.senha).toString();
  }

// Mapeie os projetos para o formato correto
user.projetos = this.selectedProjects.map((project) => ({
  id: project.project_id,
  name: project.name,
  project_id: project.project_id,
}));

// Converta a lista de projetos para uma string JSON válida sem barras invertidas adicionais e sem formatação adicional
user.projetos = JSON.stringify(user.projetos);

  this.userService.updateUser(this.userId, user).subscribe(
    (editedUser) => {
      this.message = 'Usuário atualizado com sucesso!';
      this.isSuccess = true;
      this.editedUser = editedUser;
      this.clearMessageAfterDelay();
    },
    (error) => {
      console.error('Erro ao atualizar usuário:', error);
      this.message =
        'Erro ao atualizar usuário. Verifique os campos e tente novamente.';
      this.isSuccess = false;
      this.clearMessageAfterDelay();
    }
  );
}

  private clearMessageAfterDelay(): void {
    // Limpar a mensagem após 5 segundos (5000 milissegundos)
    setTimeout(() => {
      this.message = '';
      this.isSuccess = undefined; // Limpar também o status de sucesso
    }, 5000);
  }

  goBackToList(): void {
    this.router.navigate(['/usuarios']);
  }
}
